import React, { useEffect, useState } from 'react'
import DrinksTable from './DrinksTable'

import useApi from '../../../hooks/useApi'
import { useNavigate } from 'react-router-dom';
import DrinksFormModal from "./DrinksFormModal";
import { ToastContainer, toast } from "react-toastify";
import restaurantApi from "../../../api/restaurants/restaurantApi";

const columns = [
  { name: "Title", uid: "title" },
  { name: "Packaging", uid: "packaging" },
  { name: "Units Per Pack", uid: "units_per_pack" },
  { name: "Pack Quantity", uid: "pack_quantity" },
  { name: "Unit Quantity", uid: "unit_quantity" },
  { name: "Pack Selling Price", uid: "pack_selling_price" },
  { name: "Unit Selling Price", uid: "unit_selling_price" },
  { name: "Actions", uid: "actions" },
];

function DrinksInventoryList() {
  const [openEditModal, setopenEditModal] = useState(false);

  const navigate = useNavigate();
  const [drink, setDrink] = useState();
  const [drinks, setDrinks] = useState([]);
  const [data, setdata] = useState([]);
  const [updated, setUpdated] = useState(false);
  const [modalTitle, setmodalTitle] = useState("");
  const restaurantActionsApi = useApi(restaurantApi.restaurantAction);

  const getDrinks = async () => {
    await restaurantActionsApi.request({
      action: "GetBranchBarInventory",
    });
  };
  useEffect(() => {
    setdata(drinks);
  }, [drinks]);

  useEffect(() => {
    getDrinks();
  }, []);

  const handleFilter = (e) => {
    console.log("eeeee", e);
    const search_param = e;

    if (drinks && drinks.length > 0 && search_param && search_param !== "") {
      setdata(
        drinks.filter((x) => x.title.toLowerCase().includes(search_param))
      );
    } else {
      setdata(drinks);
    }
  };

  useEffect(() => {
    getDrinks();
  }, []);

  useEffect(() => {
    getDrinks();
  }, [updated]);

  const handleEditAction = (item) => {
    setopenEditModal(true);
    setDrink(item);
    setmodalTitle(`Edit ${item.tittle}`);
    setUpdated(false);
  };

  const handleAddAction = () => {
    setopenEditModal(true);
    setmodalTitle("Add new inventory item");
    setDrink(null);
  };
  const handleDetailsAction = (item) => {
    navigate(`/routes/details/${item.id}`, {
      state: {
        item: item,
      },
    });
  };
  const handleDeleteAction = (item) => {
    console.log("Item", item);
    navigate(`/routes/delete/${item.id}`);
  };

  useEffect(() => {
    if (restaurantActionsApi.data && restaurantActionsApi.data.length) {
      setDrinks(restaurantActionsApi.data);
    }

    if (
      restaurantActionsApi.data &&
      restaurantActionsApi.data.response_message &&
      restaurantActionsApi.data.response_code === 1
    ) {
      toast.error(restaurantActionsApi.data.response_message);
    }

    if (
      restaurantActionsApi.data &&
      restaurantActionsApi.data.response_message &&
      restaurantActionsApi.data.response_code === 0
    ) {
      toast.success(restaurantActionsApi.data.response_message);
    }

    console.log("transportActionsApi.data", restaurantActionsApi.data);
  }, [restaurantActionsApi.data]);

  useEffect(() => {
    getDrinks();
  }, [updated]);

  return (
    <div>
      <ToastContainer position="bottom-center" theme="colored" />
      {openEditModal && (
        <DrinksFormModal
          ismodalOpen={openEditModal}
          setisModalOpen={setopenEditModal}
          inventoryToEdit={drink}
          updated={updated}
          setUpdated={setUpdated}
          modalTitle={modalTitle}
        />
      )}
      <DrinksTable
        data={data}
        columns={columns}
        editAction={handleEditAction}
        detailsAction={handleDetailsAction}
        deleteAction={handleDeleteAction}
        addAction={handleAddAction}
        handleFilter={handleFilter}
        updated={updated}
        setUpdated={setUpdated}
      />
    </div>
  );
}

export default DrinksInventoryList